277		public static void removeInstanceName(Context context, int instance, int activeInstance)
278		{
279			SharedPreferences preferences = getPreferences(context);
280			SharedPreferences.Editor editor = preferences.edit();
281	
282			int newInstance = instance + 1;
283	
284			String server = preferences.getString(Constants.PREFERENCES_KEY_SERVER + newInstance, null);
285			String serverName = preferences.getString(Constants.PREFERENCES_KEY_SERVER_NAME + newInstance, null);
286			String serverUrl = preferences.getString(Constants.PREFERENCES_KEY_SERVER_URL + newInstance, null);
287			String userName = preferences.getString(Constants.PREFERENCES_KEY_USERNAME + newInstance, null);
288			String password = preferences.getString(Constants.PREFERENCES_KEY_PASSWORD + newInstance, null);
289			boolean serverEnabled = preferences.getBoolean(Constants.PREFERENCES_KEY_SERVER_ENABLED + newInstance, true);
290			boolean jukeboxEnabled = preferences.getBoolean(Constants.PREFERENCES_KEY_JUKEBOX_BY_DEFAULT + newInstance, true);
291	
292			editor.putString(Constants.PREFERENCES_KEY_SERVER + instance, server);
293			editor.putString(Constants.PREFERENCES_KEY_SERVER_NAME + instance, serverName);
294			editor.putString(Constants.PREFERENCES_KEY_SERVER_URL + instance, serverUrl);
295			editor.putString(Constants.PREFERENCES_KEY_USERNAME + instance, userName);
296			editor.putString(Constants.PREFERENCES_KEY_PASSWORD + instance, password);
297			editor.putBoolean(Constants.PREFERENCES_KEY_SERVER_ENABLED + instance, serverEnabled);
298			editor.putBoolean(Constants.PREFERENCES_KEY_JUKEBOX_BY_DEFAULT + instance, jukeboxEnabled);
299	
300			editor.putString(Constants.PREFERENCES_KEY_SERVER + newInstance, null);
301			editor.putString(Constants.PREFERENCES_KEY_SERVER_NAME + newInstance, null);
302			editor.putString(Constants.PREFERENCES_KEY_SERVER_URL + newInstance, null);
303			editor.putString(Constants.PREFERENCES_KEY_USERNAME + newInstance, null);
304			editor.putString(Constants.PREFERENCES_KEY_PASSWORD + newInstance, null);
305			editor.putBoolean(Constants.PREFERENCES_KEY_SERVER_ENABLED + newInstance, true);
306			editor.putBoolean(Constants.PREFERENCES_KEY_JUKEBOX_BY_DEFAULT + newInstance, false);
307			editor.commit();
308	
309			if (instance == activeInstance)
310			{
311				Util.setActiveServer(context, 0);
312			}
313	
314			if (newInstance == activeInstance)
315			{
316				Util.setActiveServer(context, instance);
317			}
318		}
