372		public static String getRestUrl(Context context, String method)
373		{
374			StringBuilder builder = new StringBuilder(8192);
375	
376			SharedPreferences preferences = getPreferences(context);
377	
378			int instance = preferences.getInt(Constants.PREFERENCES_KEY_SERVER_INSTANCE, 1);
379			String serverUrl = preferences.getString(Constants.PREFERENCES_KEY_SERVER_URL + instance, null);
380			String username = preferences.getString(Constants.PREFERENCES_KEY_USERNAME + instance, null);
381			String password = preferences.getString(Constants.PREFERENCES_KEY_PASSWORD + instance, null);
382	
383			// Slightly obfuscate password
384			password = "enc:" + Util.utf8HexEncode(password);
385	
386			builder.append(serverUrl);
387			if (builder.charAt(builder.length() - 1) != '/')
388			{
