443		public static long copy(InputStream input, OutputStream output) throws IOException
444		{
445			byte[] buffer = new byte[1024 * 4];
446			long count = 0;
447			int n;
448	
449			while (-1 != (n = input.read(buffer)))
450			{
451				output.write(buffer, 0, n);
452				count += n;
453			}
454	
455			return count;
456		}
