458		public static void atomicCopy(File from, File to) throws IOException
459		{
460			File tmp = new File(String.format("%s.tmp", to.getPath()));
461			FileInputStream in = new FileInputStream(from);
462			FileOutputStream out = new FileOutputStream(tmp);
463	
464			try
465			{
466				in.getChannel().transferTo(0, from.length(), out.getChannel());
467				out.close();
468	
469				if (!tmp.renameTo(to))
470				{
471					throw new IOException(String.format("Failed to rename %s to %s", tmp, to));
472				}
473	
474				Log.i(TAG, String.format("Copied %s to %s", from, to));
475			}
476			catch (IOException x)
477			{
478				close(out);
479				delete(to);
480				throw x;
481			}
482			finally
483			{
484				close(in);
485				close(out);
486				delete(tmp);
487			}
488		}
