666		/**
667		 * Encodes the given string by using the hexadecimal representation of its UTF-8 bytes.
668		 *
669		 * @param s The string to encode.
670		 * @return The encoded string.
671		 */
672		public static String utf8HexEncode(String s)
673		{
674			if (s == null)
675			{
676				return null;
677			}
678	
679			byte[] utf8;
680	
681			try
682			{
683				utf8 = s.getBytes(Constants.UTF_8);
684			}
685			catch (UnsupportedEncodingException x)
686			{
687				throw new RuntimeException(x);
688			}
689	
690			return hexEncode(utf8);
691		}
692	
693		/**
694		 * Converts an array of bytes into an array of characters representing the hexadecimal values of each byte in order.
695		 * The returned array will be double the length of the passed array, as it takes two characters to represent any
696		 * given byte.
697		 *
698		 * @param data Bytes to convert to hexadecimal characters.
699		 * @return A string containing hexadecimal characters.
700		 */
701		public static String hexEncode(byte[] data)
702		{
703			int length = data.length;
704			char[] out = new char[length << 1];
705			int j = 0;
706	
707			// two characters form the hex value.
708			for (byte aData : data)
709			{
710				out[j++] = HEX_DIGITS[(0xF0 & aData) >>> 4];
711				out[j++] = HEX_DIGITS[0x0F & aData];
712			}
713	
714			return new String(out);
715		}
716	
717		/**
718		 * Calculates the MD5 digest and returns the value as a 32 character hex string.
719		 *
720		 * @param s Data to digest.
721		 * @return MD5 digest as a hex string.
722		 */
723		public static String md5Hex(String s)
724		{
725			if (s == null)
726			{
727				return null;
728			}
729	
730			try
731			{
732				MessageDigest md5 = MessageDigest.getInstance("MD5");
733				return hexEncode(md5.digest(s.getBytes(Constants.UTF_8)));
734			}
735			catch (Exception x)
736			{
737				throw new RuntimeException(x.getMessage(), x);
738			}
739		}
