1071				Entry song = currentPlaying.getSong();
1072	
1073				if (song == null)
1074				{
1075					return;
1076				}
1077	
1078				if (song != currentSong)
1079				{
1080					currentSong = song;
1081				}
1082	
1083				String title = song.getTitle();
1084				String artist = song.getArtist();
1085				String album = song.getAlbum();
1086				Integer duration = song.getDuration();
1087				Integer listSize = downloadService.getDownloads().size();
1088				Integer id = downloadService.getCurrentPlayingIndex() + 1;
1089				Integer playerPosition = downloadService.getPlayerPosition();
1090	
1091				avrcpIntent.putExtra("track", title);
1092				avrcpIntent.putExtra("track_name", title);
1093				avrcpIntent.putExtra("artist", artist);
1094				avrcpIntent.putExtra("artist_name", artist);
1095				avrcpIntent.putExtra("album", album);
1096				avrcpIntent.putExtra("album_name", album);
1097				avrcpIntent.putExtra("album_artist", artist);
1098				avrcpIntent.putExtra("album_artist_name", artist);
1099	
1100				if (Util.getShouldSendBluetoothAlbumArt(context))
1101				{
1102					File albumArtFile = FileUtil.getAlbumArtFile(context, song);
1103					avrcpIntent.putExtra("coverart", albumArtFile.getAbsolutePath());
1104					avrcpIntent.putExtra("cover", albumArtFile.getAbsolutePath());
1105				}
1106	
1107				avrcpIntent.putExtra("position", (long) playerPosition);
1108				avrcpIntent.putExtra("id", (long) id);
1109				avrcpIntent.putExtra("ListSize", (long) listSize);
1110	
1111				if (duration != null)
1112				{
1113					avrcpIntent.putExtra("duration", (long) duration);
1114				}
1115	
1116				switch (state)
1117				{
1118					case STARTED:
1119						avrcpIntent.putExtra("playing", true);
1120						break;
1121					case STOPPED:
1122						avrcpIntent.putExtra("playing", false);
1123						break;
1124					case PAUSED:
1125						avrcpIntent.putExtra("playing", false);
1126						break;
1127					case COMPLETED:
1128						avrcpIntent.putExtra("playing", false);
1129						break;
1130					default:
1131						return; // No need to broadcast.
1132				}
1133	
1134				context.sendBroadcast(avrcpIntent);
1135			}
1136		}
