1200		public static void requestAudioFocus(final Context context)
1201		{
1202			if (!hasFocus)
1203			{
1204				final AudioManager audioManager = (AudioManager) context.getSystemService(Context.AUDIO_SERVICE);
1205				hasFocus = true;
1206				audioManager.requestAudioFocus(new OnAudioFocusChangeListener()
1207				{
1208					@Override
1209					public void onAudioFocusChange(int focusChange)
1210					{
1211						DownloadService downloadService = (DownloadService) context;
1212						if ((focusChange == AudioManager.AUDIOFOCUS_LOSS_TRANSIENT || focusChange == AudioManager.AUDIOFOCUS_LOSS_TRANSIENT_CAN_DUCK) && !downloadService.isJukeboxEnabled())
1213						{
1214							if (downloadService.getPlayerState() == PlayerState.STARTED)
1215							{
1216								SharedPreferences preferences = getPreferences(context);
1217								int lossPref = Integer.parseInt(preferences.getString(Constants.PREFERENCES_KEY_TEMP_LOSS, "1"));
1218								if (lossPref == 2 || (lossPref == 1 && focusChange == AudioManager.AUDIOFOCUS_LOSS_TRANSIENT_CAN_DUCK))
1219								{
1220									lowerFocus = true;
1221									downloadService.setVolume(0.1f);
1222								}
1223								else if (lossPref == 0 || (lossPref == 1))
1224								{
1225									pauseFocus = true;
1226									downloadService.pause();
1227								}
1228							}
1229						}
1230						else if (focusChange == AudioManager.AUDIOFOCUS_GAIN)
1231						{
1232							if (pauseFocus)
1233							{
1234								pauseFocus = false;
1235								downloadService.start();
1236							}
1237							else if (lowerFocus)
1238							{
1239								lowerFocus = false;
1240								downloadService.setVolume(1.0f);
1241							}
1242						}
1243						else if (focusChange == AudioManager.AUDIOFOCUS_LOSS && !downloadService.isJukeboxEnabled())
1244						{
1245							hasFocus = false;
1246							downloadService.pause();
1247							audioManager.abandonAudioFocus(this);
1248						}
1249					}
1250				}, AudioManager.STREAM_MUSIC, AudioManager.AUDIOFOCUS_GAIN);
1251			}
1252		}
