1266		public static int calculateInSampleSize(BitmapFactory.Options options, int reqWidth, int reqHeight)
1267		{
1268			// Raw height and width of image
1269			final int height = options.outHeight;
1270			final int width = options.outWidth;
1271			int inSampleSize = 1;
1272	
1273			if (height > reqHeight || width > reqWidth)
1274			{
1275	
1276				// Calculate ratios of height and width to requested height and
1277				// width
1278				final int heightRatio = Math.round((float) height / (float) reqHeight);
1279				final int widthRatio = Math.round((float) width / (float) reqWidth);
1280	
1281				// Choose the smallest ratio as inSampleSize value, this will
1282				// guarantee
1283				// a final image with both dimensions larger than or equal to the
1284				// requested height and width.
1285				inSampleSize = heightRatio < widthRatio ? heightRatio : widthRatio;
1286			}
1287	
1288			return inSampleSize;
1289		}
