1451		public static String formatTotalDuration(long totalDuration, boolean inMilliseconds)
1452		{
1453			long millis = totalDuration;
1454	
1455			if (!inMilliseconds)
1456			{
1457				millis = totalDuration * 1000;
1458			}
1459	
1460			long hours = TimeUnit.MILLISECONDS.toHours(millis);
1461			long minutes = TimeUnit.MILLISECONDS.toMinutes(millis) - TimeUnit.HOURS.toMinutes(hours);
1462			long seconds = TimeUnit.MILLISECONDS.toSeconds(millis) - TimeUnit.MINUTES.toSeconds(hours * 60 + minutes);
1463	
1464			if (hours >= 10)
1465			{
1466				return String.format("%02d:%02d:%02d", hours, minutes, seconds);
1467			}
1468			else if (hours > 0)
1469			{
1470				return String.format("%d:%02d:%02d", hours, minutes, seconds);
1471			}
1472			else if (minutes >= 10)
1473			{
1474				return String.format("%02d:%02d", minutes, seconds);
1475			}
1476	
1477			else return minutes > 0 ? String.format("%d:%02d", minutes, seconds) : String.format("0:%02d", seconds);
1478		}
