40	public class MusicServiceFactory {
41	    private static final String LOG_TAG = MusicServiceFactory.class.getSimpleName();
42	    private static MusicService REST_MUSIC_SERVICE = null;
43	    private static MusicService OFFLINE_MUSIC_SERVICE = null;
44	
45	    public static MusicService getMusicService(Context context) {
46	        if (Util.isOffline(context)) {
47	            Log.d(LOG_TAG, "App is offline, returning offline music service.");
48	            if (OFFLINE_MUSIC_SERVICE == null) {
49	                synchronized (MusicServiceFactory.class) {
50	                    if (OFFLINE_MUSIC_SERVICE == null) {
51	                        Log.d(LOG_TAG, "Creating new offline music service");
52	                        OFFLINE_MUSIC_SERVICE = new OfflineMusicService(
53	                                createSubsonicApiClient(context),
54	                                getPermanentFileStorage(context));
55	                    }
56	                }
57	            }
58	
59	            return OFFLINE_MUSIC_SERVICE;
60	        } else {
61	            Log.d(LOG_TAG, "Returning rest music service");
62	            if (REST_MUSIC_SERVICE == null) {
63	                synchronized (MusicServiceFactory.class) {
64	                    if (REST_MUSIC_SERVICE == null) {
65	                        Log.d(LOG_TAG, "Creating new rest music service");
66	                        REST_MUSIC_SERVICE = new CachedMusicService(new RESTMusicService(
67	                                createSubsonicApiClient(context),
68	                                getPermanentFileStorage(context)));
69	                    }
70	                }
71	            }
72	
73	            return REST_MUSIC_SERVICE;
74	        }
75	    }
76	
77	    /**
78	     * Resets {@link MusicService} to initial state, so on next call to {@link #getMusicService(Context)}
79	     * it will return updated instance of it.
80	     */
81	    public static void resetMusicService() {
82	        Log.d(LOG_TAG, "Resetting music service");
83	        synchronized (MusicServiceFactory.class) {
84	            REST_MUSIC_SERVICE = null;
85	            OFFLINE_MUSIC_SERVICE = null;
86	        }
87	    }
88	
89	    private static SubsonicAPIClient createSubsonicApiClient(final Context context) {
90	        final SharedPreferences preferences = Util.getPreferences(context);
91	        int instance = preferences.getInt(Constants.PREFERENCES_KEY_SERVER_INSTANCE, 1);
92	        String serverUrl = preferences.getString(Constants.PREFERENCES_KEY_SERVER_URL + instance, null);
93	        String username = preferences.getString(Constants.PREFERENCES_KEY_USERNAME + instance, null);
94	        String password = preferences.getString(Constants.PREFERENCES_KEY_PASSWORD + instance, null);
95	        boolean allowSelfSignedCertificate = preferences
96	                .getBoolean(Constants.PREFERENCES_KEY_ALLOW_SELF_SIGNED_CERTIFICATE + instance, false);
97	        boolean enableLdapUserSupport = preferences
98	                .getBoolean(Constants.PREFERENCES_KEY_LDAP_SUPPORT + instance , false);
99	
100	        if (serverUrl == null ||
101	                username == null ||
102	                password == null) {
103	            Log.i("MusicServiceFactory", "Server credentials is not available");
104	            return new SubsonicAPIClient("http://localhost", "", "",
105	                    SubsonicAPIVersions.fromApiVersion(Constants.REST_PROTOCOL_VERSION),
106	                    Constants.REST_CLIENT_ID, allowSelfSignedCertificate,
107	                    enableLdapUserSupport, BuildConfig.DEBUG);
108	        }
109	
110	        return new SubsonicAPIClient(serverUrl, username, password,
111	                SubsonicAPIVersions.fromApiVersion(Constants.REST_PROTOCOL_VERSION),
112	                Constants.REST_CLIENT_ID, allowSelfSignedCertificate,
113	                enableLdapUserSupport, BuildConfig.DEBUG);
114	    }
115	
116	    private static PermanentFileStorage getPermanentFileStorage(final Context context) {
117	        final SharedPreferences preferences = Util.getPreferences(context);
118	        int instance = preferences.getInt(Constants.PREFERENCES_KEY_SERVER_INSTANCE, 1);
119	        final String serverId = getServerId(preferences, instance);
120	
121	        return new PermanentFileStorage(getDirectories(context), serverId, BuildConfig.DEBUG);
122	    }
123	
124	    public static String getServerId(final SharedPreferences sp, final int instance) {
125	        String serverUrl = sp.getString(
126	                Constants.PREFERENCES_KEY_SERVER_URL + instance, null);
127	        return String.valueOf(Math.abs((serverUrl + instance).hashCode()));
128	    }
129	
130	    public static Directories getDirectories(final Context context) {
131	        return new Directories() {
132	            @NotNull
133	            @Override
134	            public File getInternalCacheDir() {
135	                return context.getCacheDir();
136	            }
137	
138	            @NotNull
139	            @Override
140	            public File getInternalDataDir() {
141	                return context.getFilesDir();
142	            }
143	
144	            @Override
145	            public File getExternalCacheDir() {
146	                return context.getExternalCacheDir();
147	            }
148	        };
149	    }
