236	    private void testConnection() {
237	        ModalBackgroundTask<Boolean> task = new ModalBackgroundTask<Boolean>(getActivity(), false) {
238	            private int previousInstance;
239	
240	            @Override
241	            protected Boolean doInBackground() throws Throwable {
242	                updateProgress(R.string.settings_testing_connection);
243	
244	                final Context context = getActivity();
245	                previousInstance = Util.getActiveServer(context);
246	                Util.setActiveServer(context, serverId);
247	                try {
248	                    MusicService musicService = MusicServiceFactory.getMusicService(context);
249	                    musicService.ping(context, this);
250	                    return musicService.isLicenseValid(context, null);
251	                } finally {
252	                    Util.setActiveServer(context, previousInstance);
253	                }
254	            }
255	
256	            @Override
257	            protected void done(Boolean licenseValid) {
258	                if (licenseValid) {
259	                    Util.toast(getActivity(), R.string.settings_testing_ok);
260	                } else {
261	                    Util.toast(getActivity(), R.string.settings_testing_unlicensed);
262	                }
263	            }
264	
265	            @Override
266	            protected void cancel() {
267	                super.cancel();
268	                Util.setActiveServer(getActivity(), previousInstance);
269	            }
270	
271	            @Override
272	            protected void error(Throwable error) {
273	                Log.w(LOG_TAG, error.toString(), error);
274	                new ErrorDialog(getActivity(), String.format("%s %s", getResources().getString(R.string.settings_connection_failure), getErrorMessage(error)), false);
275	            }
276	        };
277	        task.execute();
278	    }
