287	                MusicServiceFactory.getDirectories(getActivity()),
288	                storageServerId,
289	                BuildConfig.DEBUG
290	        );
291	        fileStorage.clearAll();
292	
293	        // Reset values to null so when we ask for them again they are new
294	        sharedPreferences.edit()
295	                .remove(Constants.PREFERENCES_KEY_SERVER_NAME + serverId)
296	                .remove(Constants.PREFERENCES_KEY_SERVER_URL + serverId)
297	                .remove(Constants.PREFERENCES_KEY_USERNAME + serverId)
298	                .remove(Constants.PREFERENCES_KEY_PASSWORD + serverId)
299	                .remove(Constants.PREFERENCES_KEY_SERVER_ENABLED + serverId)
300	                .remove(Constants.PREFERENCES_KEY_JUKEBOX_BY_DEFAULT + serverId)
301	                .remove(Constants.PREFERENCES_KEY_ALLOW_SELF_SIGNED_CERTIFICATE + serverId)
302	                .apply();
303	
304	        if (serverId < activeServers) {
305	            int activeServer = Util.getActiveServer(getActivity());
306	            for (int i = serverId; i <= activeServers; i++) {
307	                Util.removeInstanceName(getActivity(), i, activeServer);
308	            }
309	        }
310	
311	        activeServers--;
312	
313	        sharedPreferences.edit()
314	                .putInt(Constants.PREFERENCES_KEY_ACTIVE_SERVERS, activeServers)
315	                .apply();
316	
317	        getActivity().finish();
318	    }
